package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.WorkflowJobEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.WorkflowJobMapper; import org.springframework.stereotype.Repository; import java.time.LocalDateTime; import java.util.*;
@Repository public class MybatisWorkflowJobRepository implements WorkflowJobRepository { private final WorkflowJobMapper mapper; public MybatisWorkflowJobRepository(WorkflowJobMapper mapper){this.mapper=mapper;} public int insert(WorkflowJobEntity e){return mapper.insert(e);} public Optional<WorkflowJobEntity> findById(String id){return Optional.ofNullable(mapper.selectById(id));} public List<WorkflowJobEntity> findByWorkflowId(String id){return mapper.selectList(new LambdaQueryWrapper<WorkflowJobEntity>().eq(WorkflowJobEntity::getWorkflowId,id));} public int updateStatusIfVersionMatches(String id,long version,String status){return mapper.update(null,new LambdaUpdateWrapper<WorkflowJobEntity>().eq(WorkflowJobEntity::getJobId,id).eq(WorkflowJobEntity::getLeaseVersion,version).set(WorkflowJobEntity::getStatus,status).set(WorkflowJobEntity::getUpdatedAt,LocalDateTime.now()));} }
